/**
 * @summary Moderate a piece of content (approve/remove)
 */
export const getModerateContentUrl = (postId: string) => {
  return `/api/admin/content/${postId}/moderate`;
};

export const moderateContent = async (
  postId: string,
  moderateContentBody: ModerateContentBody,
  options?: RequestInit,
): Promise<Post> => {
  return customFetch<Post>(getModerateContentUrl(postId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(moderateContentBody),
  });
};

export const getModerateContentMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof moderateContent>>,
    TError,
    { postId: string; data: BodyType<ModerateContentBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof moderateContent>>,
  TError,
  { postId: string; data: BodyType<ModerateContentBody> },
  TContext
> => {
  const mutationKey = ["moderateContent"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof moderateContent>>,
    { postId: string; data: BodyType<ModerateContentBody> }
  > = (props) => {
    const { postId, data } = props ?? {};

    return moderateContent(postId, data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type ModerateContentMutationResult = NonNullable<
  Awaited<ReturnType<typeof moderateContent>>
>;
export type ModerateContentMutationBody = BodyType<ModerateContentBody>;
